INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (24, 102301, "2030/12/17 14:59:59", 401, "2020/07/31 12:00:00", 24001, "アヤネ", 10046, 0.0, 2, 0.0, 2, 0.0, "やったね、ぷうきち！\nこれならお兄ちゃんたちの\nお手本になれたよね！");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (24, 102301, "2030/12/17 14:59:59", 402, "2020/07/31 12:00:00", 24002, "アヤネ", 10046, 0.0, 2, 2.21, 1, 0.0, "私たちの勝ちだね！\nぷうきちと一緒なら\nどんなボールでも\nホームランを打ってみせるよ！");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (24, 102301, "2030/12/17 14:59:59", 403, "2020/07/31 12:00:00", 24003, "アヤネ", 10046, 0.0, 2, 0.0, 2, 0.0, "やったやったぁ！\nお兄ちゃん、見ててくれた？\n私、すっごくがんばったよ！");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (24, 192201, "2030/12/17 14:59:59", 701, "2020/07/31 12:00:00", 24004, "アサヒ", 10046, 0.0, 1, 1.99, 2, 0.0, "特訓の成果が出たみたいだ！\nもっと練習を重ねて\nこの調子で上達していこう！");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (24, 192201, "2030/12/17 14:59:59", 702, "2020/07/31 12:00:00", 24005, "アサヒ", 10046, 0.0, 2, 2.21, 1, 0.0, "よし、いい感じだ！\nキャプテンとしての仕事は\nきっちり果たせそうだよ");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (24, 192201, "2030/12/17 14:59:59", 703, "2020/07/31 12:00:00", 24006, "アサヒ", 10046, 0.0, 1, 3.33, 2, 0.0, "試合に向けて\nいい感覚を掴めた気がするよ！\nこのまま一気に全国大会だ！");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (24, 192301, "2030/12/17 14:59:59", 801, "2020/07/31 12:00:00", 24007, "部員３", 10046, 0.0, 2, 0.0, 2, 0.0, "このくらい余裕だ\nオレたちは全国大会を\n目指してるんだからな");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (24, 192301, "2030/12/17 14:59:59", 802, "2020/07/31 12:00:00", 24008, "部員３", 10046, 0.0, 2, 2.68, 1, 0.0, "オレだって\nビーチベースボール選手だ\nどんな球だろうが\n全部スタンドまで飛ばしてやる");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (24, 192301, "2030/12/17 14:59:59", 803, "2020/07/31 12:00:00", 24009, "部員３", 10046, 0.0, 2, 0.0, 2, 0.0, "いい感じだ\nこれなら試合でも活躍できそうだ\n大暴れしてやる！");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (24, 192501, "2030/12/17 14:59:59", 501, "2020/07/31 12:00:00", 24010, "", 10046, 0.0, 1, 0.0, 1, 0.0, "やった！");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (24, 192501, "2030/12/17 14:59:59", 502, "2020/07/31 12:00:00", 24011, "", 10046, 0.0, 1, 0.0, 1, 0.0, "勝ったよ！");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (24, 192501, "2030/12/17 14:59:59", 503, "2020/07/31 12:00:00", 24012, "", 10046, 0.0, 1, 0.0, 1, 0.0, "いい調子！");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (24, 113501, "2030/12/17 14:59:59", 111, "2020/07/31 12:00:00", 24013, "ミサト", 10046, 0.0, 2, 5.33, 6, 0.0, "あら～…もしかして\n勝っちゃったのかしら？\nみんなの練習を見ていたから\nかもしれないわね");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (24, 113501, "2030/12/17 14:59:59", 112, "2020/07/31 12:00:00", 24014, "ミサト", 10046, 0.0, 2, 6.85, 1, 0.0, "みんなの力になりたくて\n先生も頑張ってみました～！\nうまく投げられたみたいで\nよかったわ～！");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (24, 113501, "2030/12/17 14:59:59", 113, "2020/07/31 12:00:00", 24015, "ミサト", 10046, 0.0, 2, 3.0, 1, 0.0, "練習お疲れさま～！\n先生も協力できて\nとってもうれしいわ～♪\n次も頑張りましょうね～！");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (24, 192401, "2030/12/17 14:59:59", 611, "2020/07/31 12:00:00", 24016, "ダイチ", 10046, 0.0, 2, 6.11, 1, 0.0, "まだ練習が足りねえみてえだな\nこれっぽっちも本気で\n投げてねえっつーの\nもう一回やんぞ！");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (24, 192401, "2030/12/17 14:59:59", 612, "2020/07/31 12:00:00", 24017, "ダイチ", 10046, 0.0, 2, 6.75, 1, 0.0, "ふん、当然の結果だな\n俺の球は、誰にも打てねえよ！\nまたやりてえっつーなら\nとことん付き合ってやるぜ！");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (24, 192401, "2030/12/17 14:59:59", 613, "2020/07/31 12:00:00", 24018, "ダイチ", 10046, 0.0, 2, 0.0, 2, 0.0, "おっしゃあ！\nこの勢いで全国に行ってやるぜ！\n全員三振で仕留めてやる！");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (24, 113401, "2030/12/17 14:59:59", 211, "2020/07/31 12:00:00", 24019, "ハツネ", 10046, 0.0, 1, 4.52, 2, 0.0, "きらーん☆\nハツネちゃんの大勝利なのだ～！\nみんながもっと上達できるように\n私もまだまだ頑張るからね！");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (24, 113401, "2030/12/17 14:59:59", 212, "2020/07/31 12:00:00", 24020, "ハツネ", 10046, 0.0, 1, 3.89, 2, 0.0, "やったあ！　私の勝ちだね！\nチアリーダーもピッチャーも\nハツネちゃんに任せてよ！");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (24, 113401, "2030/12/17 14:59:59", 213, "2020/07/31 12:00:00", 24021, "ハツネ", 10046, 0.0, 2, 13.49, 1, 0.0, "よお～し、この調子でもっと\n頑張ろう…と思ったけど\n超能力を使ったから…\n眠くなってきちゃった…すやぁ…");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (24, 106501, "2030/12/17 14:59:59", 311, "2020/07/31 12:00:00", 24022, "カヤ", 10046, 0.0, 2, 3.17, 1, 0.0, "いい勝負だったぜ！\nたぎっちまって\nつい本気で投げちまったよ");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (24, 106501, "2030/12/17 14:59:59", 312, "2020/07/31 12:00:00", 24023, "カヤ", 10046, 0.0, 2, 4.42, 1, 0.0, "どうだ？\nオレ様のボールは熱かっただろ！\nま、でもおまえらの根性も\nなかなかのもんだったぜ");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (24, 106501, "2030/12/17 14:59:59", 313, "2020/07/31 12:00:00", 24024, "カヤ", 10046, 0.0, 1, 2.89, 6, 0.0, "なんだよ、そんなもんか？\nこっちはまだまだ投げたりねえ\nもっと勝負しようぜ！");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (24, 102301, "2030/12/17 14:59:59", 421, "2020/07/31 12:00:00", 24025, "アヤネ", 10046, 0.0, 3, 3.71, 4, 0.0, "あとちょっとだったのに～！\n次こそぷうきちと一緒に\n勝ってみせるからね！");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (24, 192201, "2030/12/17 14:59:59", 721, "2020/07/31 12:00:00", 24026, "アサヒ", 10046, 0.0, 1, 5.1, 2, 0.0, "いい勝負だったね！\nでも、やっぱり悔しいな…\nもっと練習して\n今度は絶対に俺が勝つから！");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (24, 192301, "2030/12/17 14:59:59", 821, "2020/07/31 12:00:00", 24027, "部員３", 10046, 0.0, 3, 4.34, 1, 0.0, "ちっ…あと一歩足りなかったか\n次こそは絶対に勝つから\nそのつもりでいろ");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (24, 192501, "2030/12/17 14:59:59", 521, "2020/07/31 12:00:00", 24028, "", 10046, 0.0, 1, 0.0, 1, 0.0, "いい勝負だったよ\nまたやろうね");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (24, 113501, "2030/12/17 14:59:59", 101, "2020/07/31 12:00:00", 24029, "ミサト", 10046, -360.0, 2, 5.62, 1, 0.0, "とってもよくできました～♪\n頑張ってくれて先生うれしいわ\nこれからも試合に向けて\n練習していきましょうね～");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (24, 113501, "2030/12/17 14:59:59", 102, "2020/07/31 12:00:00", 24030, "ミサト", 10046, -360.0, 2, 9.58, 1, 0.0, "頑張った成果ね～！\nこのまま練習を続ければ\nもっとすごい成績を残せそうよ\n期待してますからね～！");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (24, 113501, "2030/12/17 14:59:59", 103, "2020/07/31 12:00:00", 24031, "ミサト", 10046, -360.0, 2, 0.0, 2, 0.0, "いい子、いい子～♪\n頑張り屋さんのあなたを\nたっくさん褒めてあげますからね");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (24, 113501, "2030/12/17 14:59:59", 104, "2020/07/31 12:00:00", 24032, "ミサト", 10046, -360.0, 1, 9.13, 2, 0.0, "夢に向けて、一歩前進できたわね\nこの調子で、夢を叶えましょう\n目指せ、全国大会～！");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (24, 113501, "2030/12/17 14:59:59", 105, "2020/07/31 12:00:00", 24033, "ミサト", 10046, -360.0, 2, 8.27, 1, 0.0, "絶好調ね～♪\nきっと試合でも大活躍\n間違いなしだわ\n楽しみにしていますからね～！");
